import React, { useEffect, useState, useCallback } from 'react'
import axios from 'axios'
import { Modal, Button, Spinner } from 'react-bootstrap'
import { PageTitle } from '../../../_metronic/layout/core'
import { KTIcon } from '../../../_metronic/helpers'

interface Vendor {
    seller_id: number
    nom: string
    email: string
    product_count: number
    order_count: number
    status?: string
    city?: string
    country_id?: string
    phone?: string
}

const VendorsPage: React.FC = () => {
    // 1. Existing State
    const [vendors, setVendors] = useState<Vendor[]>([])
    const [loading, setLoading] = useState<boolean>(true)
    const [error, setError] = useState<string | null>(null)
    const [searchTerm, setSearchTerm] = useState<string>('')
    const [debouncedSearch, setDebouncedSearch] = useState<string>('')
    const [selectedVendor, setSelectedVendor] = useState<Vendor | null>(null)
    const [showModal, setShowModal] = useState<boolean>(false)
    const [currentPage, setCurrentPage] = useState(1)
    const [totalPages, setTotalPages] = useState(1)
    const [totalCount, setTotalCount] = useState(0)
    const [itemsPerPage, setItemsPerPage] = useState(10)

    // Vendor Products Modal State
    const [showProductsModal, setShowProductsModal] = useState(false);
    const [vendorProducts, setVendorProducts] = useState<any[]>([]);
    const [loadingProducts, setLoadingProducts] = useState(false);

    // Debounce search term
    useEffect(() => {
        const handler = setTimeout(() => {
            setDebouncedSearch(searchTerm)
            setCurrentPage(1)
        }, 500)
        return () => clearTimeout(handler)
    }, [searchTerm])

    const fetchVendors = useCallback(async () => {
        try {
            setLoading(true)
            const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8001/api';
            const response = await axios.get(`${apiUrl}/vendeurs`, {
                params: {
                    page: currentPage,
                    limit: itemsPerPage,
                    search: debouncedSearch
                }
            })

            if (response.data.success) {
                setVendors(response.data.vendeurs)
                setTotalCount(response.data.total_count)
                setTotalPages(response.data.last_page)
            } else {
                setVendors([])
            }
            setError(null)
        } catch (err: any) {
            console.error('Vendors Fetch Error:', err)
            setError('Failed to fetch vendors from API')
            setVendors([])
        } finally {
            setLoading(false)
        }
    }, [currentPage, debouncedSearch, itemsPerPage])

    useEffect(() => {
        fetchVendors()
    }, [fetchVendors])

    const handleShowDetails = (vendor: Vendor) => {
        setSelectedVendor(vendor)
        setShowModal(true)
    }

    const handleShowProducts = async (vendor: Vendor) => {
        try {
            setSelectedVendor(vendor);
            setLoadingProducts(true);
            setShowProductsModal(true);
            const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8001/api';
            const response = await axios.get(`${apiUrl}/vendeurs/${vendor.seller_id}/products`);
            if (response.data.success) {
                setVendorProducts(response.data.products);
            }
        } catch (err) {
            console.error('Failed to fetch vendor products:', err);
        } finally {
            setLoadingProducts(false);
        }
    };

    const currentVendors = vendors;

    return (
        <>
            <PageTitle breadcrumbs={[]}>Vendors</PageTitle>
            {error && (
                <div className="alert alert-danger d-flex align-items-center p-5 mb-10">
                    <span className="svg-icon svg-icon-2hx svg-icon-danger me-4">...</span>
                    <div className="d-flex flex-column">
                        <h4 className="mb-1 text-danger">Error</h4>
                        <span>{error}</span>
                    </div>
                </div>
            )}
            <div className='card mb-5 mb-xl-8'>
                <div className='card-header border-0 pt-5'>
                    <h3 className='card-title align-items-start flex-column'>
                        <span className='card-label fw-bold fs-3 mb-1'>All Vendors</span>
                        <span className='text-muted mt-1 fw-semibold fs-7'>Total: {totalCount} vendors</span>
                    </h3>
                    <div className='card-toolbar'>
                        <div className='d-flex align-items-center position-relative my-1'>
                            <KTIcon iconName='magnifier' className='fs-1 position-absolute ms-6' />
                            <input
                                type='text'
                                className='form-control form-control-solid w-250px ps-14'
                                placeholder='Search vendors'
                                value={searchTerm}
                                onChange={(e) => {
                                    setSearchTerm(e.target.value)
                                }}
                            />
                        </div>
                    </div>
                </div>
                {/* ... existing table code ... */}
                <div className='card-body py-3'>
                    {/* ... existing table code ... */}
                    <div className='table-responsive'>
                        <table className='table table-row-bordered table-row-gray-100 align-middle gs-0 gy-3'>
                            <thead>
                                <tr className='fw-bold text-muted'>
                                    <th className='min-w-150px'>Nom</th>
                                    <th className='min-w-150px'>Email</th>
                                    <th className='min-w-120px'>Tél</th>
                                    <th className='min-w-120px text-center'>Produits</th>
                                    <th className='min-w-120px text-center'>Commandes</th>

                                    <th className='min-w-120px text-end'>Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {loading ? (
                                    [...Array(5)].map((_, index) => (
                                        <tr key={index}>
                                            <td colSpan={6}>
                                                <span className="placeholder-glow">
                                                    <span className="placeholder col-12 py-3"></span>
                                                </span>
                                            </td>
                                        </tr>
                                    ))
                                ) : (
                                    currentVendors.map((vendor) => (
                                        <tr key={vendor.seller_id}>
                                            <td>
                                                <div className='d-flex align-items-center'>
                                                    <div className='symbol symbol-45px me-5'>
                                                        <span className='symbol-label bg-light-primary text-primary fw-bold'>
                                                            {vendor.nom.charAt(0)}
                                                        </span>
                                                    </div>
                                                    <div className='d-flex justify-content-start flex-column'>
                                                        <button
                                                            className='btn btn-link text-dark fw-bold text-hover-primary fs-6 p-0 text-start'
                                                            onClick={() => handleShowDetails(vendor)}
                                                        >
                                                            {vendor.nom}
                                                        </button>
                                                    </div>
                                                </div>
                                            </td>
                                            <td className='text-dark fw-bold fs-7'>{vendor.email}</td>
                                            <td className='text-dark fw-bold fs-7'>{vendor.phone || 'N/A'}</td>
                                            <td className='text-center'>
                                                <button
                                                    className='btn btn-link btn-color-primary btn-active-color-primary fw-bold p-0'
                                                    onClick={() => handleShowProducts(vendor)}
                                                >
                                                    {vendor.product_count} articles
                                                </button>
                                            </td>
                                            <td className='text-center'>
                                                <span className='badge badge-light-success fw-bold'>{vendor.order_count} commandes</span>
                                            </td>

                                            <td className='text-end'>
                                                <button
                                                    className='btn btn-icon btn-light-info btn-active-info btn-sm me-1'
                                                    onClick={() => handleShowDetails(vendor)}
                                                    title="View Statistics"
                                                >
                                                    <KTIcon iconName='graph-3' className='fs-3' />
                                                </button>
                                                <button
                                                    className='btn btn-icon btn-light-primary btn-active-primary btn-sm'
                                                    title="Edit Seller"
                                                >
                                                    <KTIcon iconName='pencil' className='fs-3' />
                                                </button>
                                            </td>
                                        </tr>
                                    ))
                                )}
                                {!loading && currentVendors.length === 0 && (
                                    <tr>
                                        <td colSpan={6} className='text-center'>No vendors found</td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                    {/* Pagination */}
                    {totalCount > 0 && (
                        <div className="d-flex justify-content-between align-items-center mt-4 pt-10 px-9 pb-9">
                            <div className="d-flex align-items-center">
                                <span className="text-gray-600 me-3 fw-semibold">Lignes par page:</span>
                                <select
                                    className="form-select form-select-sm form-select-solid w-75px"
                                    value={itemsPerPage}
                                    onChange={(e) => {
                                        setItemsPerPage(Number(e.target.value));
                                        setCurrentPage(1);
                                    }}
                                >
                                    <option value={10}>10</option>
                                    <option value={20}>20</option>
                                    <option value={50}>50</option>
                                    <option value={100}>100</option>
                                </select>
                            </div>

                            <div className="d-flex align-items-center">
                                <span className="fs-6 fw-semibold text-gray-700 me-5">
                                    Page {currentPage} sur {Math.max(1, totalPages)} | Total: {totalCount} vendeurs
                                </span>
                                <ul className="pagination m-0">
                                    <li className={`page-item previous ${currentPage === 1 ? 'disabled' : ''}`}>
                                        <button className="page-link" onClick={() => setCurrentPage(currentPage - 1)}>
                                            <i className="previous"></i>
                                        </button>
                                    </li>

                                    {(() => {
                                        const pages: React.ReactNode[] = [];
                                        const maxVisible = 5;
                                        let start = Math.max(1, currentPage - 2);
                                        let end = Math.min(totalPages, start + maxVisible - 1);

                                        if (end - start < maxVisible - 1) {
                                            start = Math.max(1, end - maxVisible + 1);
                                        }

                                        for (let i = start; i <= end; i++) {
                                            pages.push(
                                                <li key={i} className={`page-item ${currentPage === i ? 'active' : ''}`}>
                                                    <button className="page-link" onClick={() => setCurrentPage(i)}>
                                                        {i}
                                                    </button>
                                                </li>
                                            );
                                        }
                                        return pages;
                                    })()}

                                    <li className={`page-item next ${currentPage === totalPages || totalPages === 0 ? 'disabled' : ''}`}>
                                        <button className="page-link" onClick={() => setCurrentPage(currentPage + 1)}>
                                            <i className="next"></i>
                                        </button>
                                    </li>
                                </ul>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {/* Vendor Details Modal */}
            <Modal show={showModal} onHide={() => setShowModal(false)} size='lg'>
                <Modal.Header closeButton className="bg-primary text-white">
                    <Modal.Title className="text-white">Détails du Vendeur: {selectedVendor?.nom}</Modal.Title>
                </Modal.Header>
                <Modal.Body className='py-10 px-lg-17'>
                    {selectedVendor && (
                        <div className='scroll-y me-n7 pe-7'>
                            <div className='d-flex flex-center flex-column mb-10'>
                                <div className='symbol symbol-100px symbol-circle mb-7'>
                                    <span className='symbol-label bg-light-primary text-primary fs-1 fw-bold'>
                                        {selectedVendor.nom.charAt(0)}
                                    </span>
                                </div>
                                <span className='fs-3 text-gray-800 text-hover-primary fw-bold mb-1'>
                                    {selectedVendor.nom}
                                </span>
                                <div className='fs-5 fw-semibold text-muted mb-6'>ID: {selectedVendor.seller_id}</div>
                            </div>

                            <div className='row mb-7'>
                                <label className='col-lg-4 fw-semibold text-muted'>Nom Complet</label>
                                <div className='col-lg-8'>
                                    <span className='fw-bold fs-6 text-gray-800'>{selectedVendor.nom}</span>
                                </div>
                            </div>

                            <div className='row mb-7'>
                                <label className='col-lg-4 fw-semibold text-muted'>Email</label>
                                <div className='col-lg-8'>
                                    <span className='fw-bold fs-6 text-gray-800'>{selectedVendor.email}</span>
                                </div>
                            </div>

                            <div className='row mb-7'>
                                <label className='col-lg-4 fw-semibold text-muted'>Téléphone</label>
                                <div className='col-lg-8'>
                                    <span className='fw-bold fs-6 text-gray-800'>{selectedVendor.phone || 'N/A'}</span>
                                </div>
                            </div>

                            <div className='row mb-7'>
                                <label className='col-lg-4 fw-semibold text-muted'>Statut</label>
                                <div className='col-lg-8'>
                                    <span className={`badge ${selectedVendor.status === '1' ? 'badge-light-success' : 'badge-light-warning'} fw-bold fs-7`}>
                                        {selectedVendor.status === '1' ? 'Actif' : 'Inactif'}
                                    </span>
                                </div>
                            </div>

                            <div className='row mb-7'>
                                <label className='col-lg-4 fw-semibold text-muted'>Localisation</label>
                                <div className='col-lg-8'>
                                    <span className='fw-bold fs-6 text-gray-800'>
                                        {selectedVendor.city ? selectedVendor.city : 'N/A'}
                                        {selectedVendor.country_id ? `, ${selectedVendor.country_id}` : ''}
                                    </span>
                                </div>
                            </div>

                            <div className='row mb-7'>
                                <label className='col-lg-4 fw-semibold text-muted'>Statistiques</label>
                                <div className='col-lg-8 d-flex gap-3'>
                                    <span className='badge badge-light-primary fw-bold fs-7'>{selectedVendor.product_count} articles</span>
                                    <span className='badge badge-light-success fw-bold fs-7'>{selectedVendor.order_count} commandes</span>
                                </div>
                            </div>
                        </div>
                    )}
                </Modal.Body>
                <Modal.Footer>
                    <button className='btn btn-light' onClick={() => setShowModal(false)}>
                        Fermer
                    </button>
                    <button className='btn btn-primary' onClick={() => setShowModal(false)}>
                        Modifier
                    </button>
                </Modal.Footer>
            </Modal>

            {/* Vendor Products Modal */}
            <Modal show={showProductsModal} onHide={() => setShowProductsModal(false)} size="xl">
                <Modal.Header closeButton className="bg-primary text-white">
                    <Modal.Title className="fw-bolder text-white">Produits de {selectedVendor?.nom}</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    {loadingProducts ? (
                        <div className="d-flex justify-content-center p-10">
                            <Spinner animation="border" variant="primary" />
                        </div>
                    ) : (
                        <div className="table-responsive">
                            <table className="table table-row-bordered table-row-gray-300 align-middle gs-0 gy-3">
                                <thead>
                                    <tr className="fw-bolder text-muted bg-light">
                                        <th className="ps-4 min-w-300px rounded-start">Nom du Produit</th>
                                        <th className="min-w-150px">SKU</th>
                                        <th className="min-w-100px text-end pe-4 rounded-end">Prix</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {vendorProducts.length > 0 ? vendorProducts.map((prod, idx) => (
                                        <tr key={idx}>
                                            <td className="ps-4">
                                                <span className="text-dark fw-bold fs-6">{prod.name}</span>
                                            </td>
                                            <td>
                                                <span className="badge badge-light-primary fw-bold">{prod.sku}</span>
                                            </td>
                                            <td className="text-end pe-4">
                                                <span className="text-success fw-bold fs-6">{Number(prod.price || 0).toFixed(2)}</span>
                                            </td>
                                        </tr>
                                    )) : (
                                        <tr>
                                            <td colSpan={3} className="text-center py-10 text-muted">Aucun produit trouvé</td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    )}
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="light" onClick={() => setShowProductsModal(false)}>Fermer</Button>
                </Modal.Footer>
            </Modal>
        </>
    )
}

export default VendorsPage
